package app.loveu;
import org.json.*;import java.util.*;import java.security.*;
public class BulkShareTest {
 static void check(boolean value,String label){if(!value)throw new AssertionError(label);}interface Job{void run()throws Exception;}static void rejected(Job j)throws Exception{try{j.run();throw new AssertionError("accepted stale or wrong owner");}catch(SecurityException|IllegalStateException expected){}}
 static JSONObject account(String id,String other,KeyPair a,KeyPair b)throws Exception{return new JSONObject().put("id",id).put("token","test-only-token").put("pairId","synthetic-pair").put("publicKey",CoupleCrypto.publicEncoded(a)).put("privateKey",CoupleCrypto.privateEncoded(a)).put("peer",new JSONObject().put("id",other).put("publicKey",CoupleCrypto.publicEncoded(b)));}
 static JSONObject event(int n)throws Exception{return new JSONObject().put("id","event-"+n).put("date","2020-09-01").put("time","21:30:17").put("durationMillis",1234567L).put("protection","安全套").put("note","private note").put("place","private location").put("latitude",1.2).put("longitude",2.3).put("unknown","retained only locally");}
 public static void main(String[] args)throws Exception{
  KeyPair me=CoupleCrypto.generateIdentity(),peer=CoupleCrypto.generateIdentity();JSONObject c=account("self","peer",me,peer),receiver=account("peer","self",peer,me),root=new JSONObject().put("couple",c).put("events",new JSONArray()).put("settings",new JSONObject().put("futureSetting","keep"));
  for(int i=0;i<702;i++)root.getJSONArray("events").put(event(i));String before=root.toString();BulkShare.Plan plan=BulkShare.plan(root,"sex",false);check(plan.items.size()==702,"all records planned without cap");JSONObject queued=BulkShare.queuedCouple(root,plan);check(root.toString().equals(before),"preparation never changes personal records or source account");JSONArray out=queued.getJSONArray("outbox");check(out.length()==702,"all durably queueable envelopes");Set<String> seen=new HashSet<>();
  for(int i=0;i<out.length();i++){JSONObject envelope=out.getJSONObject(i);check(seen.add(envelope.getString("id")),"unique envelope id");JSONObject payload=new JSONObject(CoupleCrypto.decrypt(receiver.getString("privateKey"),c.getString("publicKey"),c.getString("pairId"),c.getString("id"),"sharedRecord",envelope.getString("id"),envelope.getString("nonce"),envelope.getString("ciphertext")));JSONObject data=payload.getJSONObject("data");check(data.getString("time").equals("21:30:17")&&data.getLong("durationMillis")==1234567L,"exact time and milliseconds");check(!data.has("note")&&!data.has("unknown")&&data.isNull("place")&&data.isNull("latitude"),"private fields never sent");SharedCoupleRecords.apply(receiver,payload,"self");}
  check(receiver.getJSONObject("sharedRecords").length()==702,"independent receiver projects every existing-protocol card");root.put("couple",queued);check(BulkShare.plan(root,"sex",false).items.isEmpty(),"repeated bulk action creates no duplicates");check(BulkShare.progress(queued).contains("0 / 702")&&BulkShare.progress(queued).contains("待发 702"),"queued not reported delivered");
  JSONObject firstJob=queued.getJSONArray("bulkShareJobs").getJSONObject(0).getJSONArray("records").getJSONObject(0);queued.getJSONObject("sharedRecords").getJSONObject(firstJob.getString("key")).getJSONObject("receipts").put("peer:"+firstJob.getString("operationId"),true);check(BulkShare.progress(queued).contains("1 / 702"),"per-operation authenticated receipt progress");
  queued.getJSONObject("sharedRecords").getJSONObject(firstJob.getString("key")).put("withdrawn",true);check(BulkShare.plan(root,"sex",false).withdrawn==1,"withdrawal tombstone preserved");
  root.put("couple",c);BulkShare.Plan one=BulkShare.plan(new JSONObject().put("couple",c).put("events",new JSONArray().put(event(0))),"sex",true);check(one.items.get(0).getJSONObject("data").getString("place").equals("private location"),"explicit location opt-in");
  JSONObject changed=new JSONObject(root.toString());changed.getJSONArray("events").getJSONObject(0).put("time","22:00:00");rejected(()->BulkShare.queuedCouple(changed,plan));changed.getJSONArray("events").remove(0);rejected(()->BulkShare.queuedCouple(changed,plan));JSONObject otherPair=new JSONObject(root.toString());otherPair.getJSONObject("couple").put("pairId","different");rejected(()->BulkShare.queuedCouple(otherPair,plan));
  JSONObject newRecord=new JSONObject(root.toString());newRecord.getJSONArray("events").put(event(999));check(BulkShare.queuedCouple(newRecord,plan).getJSONArray("outbox").length()==702,"new unreviewed record excluded from accepted snapshot");
  JSONArray pending=new JSONArray(out.toString());pending.put(new JSONObject().put("id","chat-priority").put("type","text"));check(CoupleDeliveryQueue.page(pending).getJSONObject(0).getString("id").equals("chat-priority"),"chat and receipts ahead of bulk");check(CoupleDeliveryQueue.page(pending).length()==12,"bounded sync round");check(CoupleDeliveryQueue.page(queued,100000).length()==8,"eight bulk records per paced round");queued.put("bulkNextSendAt",130000);check(CoupleDeliveryQueue.page(queued,100001).length()==0,"foreground/background share durable bulk cooldown");check(CoupleDeliveryQueue.page(queued,130000).length()==8,"cooldown resumes without deleting items");JSONObject wire=CoupleDeliveryQueue.wire(pending.getJSONObject(0));check(!wire.has("bulkBatchId")&&pending.getJSONObject(0).has("bulkBatchId"),"local job metadata stripped only from transport copy");
  int sent=0;Set<String> delivered=new HashSet<>();while(pending.length()>0){JSONArray page=CoupleDeliveryQueue.page(pending);for(int i=0;i<page.length();i++){String id=page.getJSONObject(i).getString("id");if(sent==3){check(pending.length()==700,"simulated interrupted transmission retains rest");sent++;break;}check(delivered.add(id),"resume sends each removed item once");CoupleDeliveryQueue.remove(pending,id);sent++;}}check(delivered.size()==703,"partial retry drains all without loss");
  JSONObject periods=new JSONObject().put("couple",c).put("events",new JSONArray()).put("menstrualSelf",new JSONArray()).put("menstrualPartner",new JSONArray());for(int n=0;n<100;n++){String start=java.time.LocalDate.of(2017,1,1).plusDays(n*28L).toString();periods.getJSONArray("menstrualSelf").put(new JSONObject().put("id","p-"+n).put("start",start).put("end",java.time.LocalDate.parse(start).plusDays(4).toString()).put("symptoms","private"));}periods.getJSONArray("menstrualPartner").put(new JSONObject().put("id","partner-period").put("start","2026-09-01").put("end","2026-09-05"));BulkShare.Plan pp=BulkShare.plan(periods,"period",false);check(pp.items.size()==101,"all historical periods plus partner records");check(pp.items.get(100).getString("subject").equals("peer"),"partner period belongs to correct participant");check(!pp.items.get(0).getJSONObject("data").has("symptoms"),"period notes stay private");check(PeriodRecords.entries(periods,false).size()==100,"all years included in period analysis without pruning");
  JSONObject unionRoot=new JSONObject(periods.toString());JSONObject unionCouple=BulkShare.queuedCouple(periods,pp);unionRoot.put("couple",unionCouple);check(PeriodRecords.entries(unionRoot,false).size()==100&&PeriodRecords.entries(unionRoot,true).size()==1,"shared/local same-start dedupe and subject isolation");unionRoot.put("menstrualSelf",new JSONArray());check(PeriodRecords.entries(unionRoot,false).size()==100,"received-only historical periods used in analysis");String earliest=pp.items.get(0).getJSONObject("data").getString("start");unionRoot.getJSONArray("menstrualSelf").put(new JSONObject().put("start",earliest).put("end",java.time.LocalDate.parse(earliest).plusDays(2).toString()));check(PeriodForecast.analyze(PeriodRecords.entries(unionRoot,false),java.time.LocalDate.of(2026,10,13)).lengths.get(earliest)==3,"local correction takes priority without overwriting shared data");
  System.out.println("BulkShareTest PASS 702 encrypted records independently decrypted/projected; privacy/exact time; repeat/stale/pair/withdraw safeguards; bounded priority/resume; 101 periods with ownership and long-term history");
 }
}
